(27132, 'John 4:13', 'John', 4, 13, 'عیسی وویل: «هرڅوک چې دا اوبه وڅښي نو بیا به هم تږی شي،', 'عیسی وویل: «هرچوک چې دا اوبه وچشی نو بیا به هم تزی شی،', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27133, 'John 4:14', 'John', 4, 14, 'خو کومې اوبه چې زه یې ورکوم او هرڅوک یې چې وڅښي، نو هېڅکله به تږی نه شي. زه چې هغه ته کومې اوبه ورکوم هغه اوبه به په هغه کس کې د چینې په شان بهیږي او تلپاتې ژوندون به ورته ورکوي.»', 'خو کومې اوبه چې زه یې ورکوم او هرچوک یې چې وچشی، نو هېچکله به تزی نه شی. زه چې هغه ته کومې اوبه ورکوم هغه اوبه به په هغه کس کې د چینې په شان بهیزی او تلپاتې ژوندون به ورته ورکوی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27134, 'John 4:15', 'John', 4, 15, 'ښځې وویل: «ښاغلیه، هغه اوبه ماته راکړه چې بیا هېڅکله تږې نه شم او نه به بیا د اوبو وړلو دپاره دلته راځم.»', 'شجې وویل: «شاغلیه، هغه اوبه ماته راکره چې بیا هېچکله تزې نه شم او نه به بیا د اوبو ورلو دپاره دلته راجم.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27135, 'John 4:16', 'John', 4, 16, 'عیسی ورته وویل: «لاړه شه، مېړه ته دې غږ وکړه او بېرته ورسره راشه.»', 'عیسی ورته وویل: «لاره شه، مېره ته دې غز وکره او بېرته ورسره راشه.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27136, 'John 4:17', 'John', 4, 17, 'هغې په ځواب کې وویل: «زه مېړه نه لرم.» عیسی هغې ته وویل: «ته رښتیا وایې چې مېړه نه لرې،', 'هغې په جواب کې وویل: «زه مېره نه لرم.» عیسی هغې ته وویل: «ته رشتیا وایې چې مېره نه لرې،', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27137, 'John 4:18', 'John', 4, 18, 'ځکه چې تا پنځه مېړونه کړي وو او اوس چې ته د کوم سړي سره اوسېږې هغه ستا مېړه نه دی. تا چې څه وویل هغه رښتیا دي.»', 'جکه چې تا پنجه مېرونه کری وو او اوس چې ته د کوم سری سره اوسېزې هغه ستا مېره نه دی. تا چې چه وویل هغه رشتیا دی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27138, 'John 4:19', 'John', 4, 19, 'ښځې وویل: «ښاغلیه، زه پوهېږم چې ته پیغمبر یې.', 'شجې وویل: «شاغلیه، زه پوهېزم چې ته پیغمبر یې.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27139, 'John 4:20', 'John', 4, 20, 'زمونږ نیکونو په دې غره کې عبادت کاوه، خو تاسو یهودیان وایئ چې اورشلیم یوازېنی ځای دی چې باید د خدای عبادت په کې وشي.»', 'زمونز نیکونو په دې غره کې عبادت کاوه، خو تاسو یهودیان وایی چې اورشلیم یوازېنی جای دی چې باید د خدای عبادت په کې وشی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27140, 'John 4:21', 'John', 4, 21, 'عیسی هغې ته وویل: «ای ښځې، په ما باندې باور وکړه، هغه وخت به راشي چې تاسو به نه په دې غره کې د اسماني پلار عبادت وکړئ او نه هم په اورشلیم کې.', 'عیسی هغې ته وویل: «ای شجې، په ما باندې باور وکره، هغه وخت به راشی چې تاسو به نه په دې غره کې د اسمانی پلار عبادت وکری او نه هم په اورشلیم کې.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27141, 'John 4:22', 'John', 4, 22, 'تاسو سامریان هغه چاته عبادت کوئ چې نه یې پېژنئ، خو مونږ یهودیان د هغه چا عبادت کوو چې مونږ یې پېژنو، ځکه چې خلاصون د یهودیانو په وسیله رامنځته کیږي.', 'تاسو سامریان هغه چاته عبادت کوی چې نه یې پېژنی، خو مونز یهودیان د هغه چا عبادت کوو چې مونز یې پېژنو، جکه چې خلاصون د یهودیانو په وسیله رامنجته کیزی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27142, 'John 4:23', 'John', 4, 23, 'خو هغه وخت به راشي بلکې اوس راغلی دی چې رښتیني عبادت کوونکي به د خدای د روح سره په رښتیني توګه د اسماني پلار عبادت کوي، ځکه چې اسماني پلار دا ډول عبادت کوونکي غواړي.', 'خو هغه وخت به راشی بلکې اوس راغلی دی چې رشتینی عبادت کوونکی به د خدای د روح سره په رشتینی توګه د اسمانی پلار عبادت کوی، جکه چې اسمانی پلار دا دول عبادت کوونکی غواری.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27143, 'John 4:24', 'John', 4, 24, 'خدای روح دی او هرڅوک چې د هغه عبادت کوي نو هغه دې په روح او حقیقت سره د هغه عبادت وکړي.»', 'خدای روح دی او هرچوک چې د هغه عبادت کوی نو هغه دې په روح او حقیقت سره د هغه عبادت وکری.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27144, 'John 4:25', 'John', 4, 25, 'ښځې ورته وویل: «زه پوهېږم چې د خدای مسیح راتلونکی دی او کله چې هغه راشي، نو هرڅه به مونږ ته ښکاره کړي.»', 'شجې ورته وویل: «زه پوهېزم چې د خدای مسیح راتلونکی دی او کله چې هغه راشی، نو هرچه به مونز ته شکاره کری.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
