(27146, 'John 4:27', 'John', 4, 27, 'په دې وخت کې د عیسی شاګردان بېرته راغلل او کله چې هغوی ولیدل چې هغه د یوې ښځې سره خبرې کوي، نو حیران شول خو په هغوی کې یو هم پوښتنه ونه کړه: «ته د هغې نه څه غواړې؟» یا «ته ولې د هغې سره خبرې کوې؟»', 'په دې وخت کې د عیسی شاګردان بېرته راغلل او کله چې هغوی ولیدل چې هغه د یوې شجې سره خبرې کوی، نو حیران شول خو په هغوی کې یو هم پوشتنه ونه کره: «ته د هغې نه چه غوارې؟» یا «ته ولې د هغې سره خبرې کوې؟»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27147, 'John 4:28', 'John', 4, 28, 'نو ښځې خپل منګی پرېښود، بېرته ښار ته لاړه او خلکو ته یې وویل:', 'نو شجې خپل منګی پرېشود، بېرته شار ته لاره او خلکو ته یې وویل:', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27148, 'John 4:29', 'John', 4, 29, '«راشئ او یو داسې سړی ووینئ چې ما تر‌اوسه پورې هرڅه کړي دي هغه یې راته وویل. کېدای شي چې هغه مسیح وي؟»', '«راشی او یو داسې سری ووینی چې ما تر‌اوسه پورې هرچه کری دی هغه یې راته وویل. کېدای شی چې هغه مسیح وی؟»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27149, 'John 4:30', 'John', 4, 30, 'نو هغوی د ښار نه ووتل او عیسی ته ورغلل.', 'نو هغوی د شار نه ووتل او عیسی ته ورغلل.', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
(27150, 'John 4:31', 'John', 4, 31, 'په دې وخت کې شاګردانو د عیسی نه په کلکه وغوښتل: «استاذه، یو څه وخوره.»', 'په دې وخت کې شاګردانو د عیسی نه په کلکه وغوشتل: «استاذه، یو چه وخوره.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237834, 1761237834),
